const UserInfobar = () => {
  const userName = "Hixen Haxen"
  return (
    <div className='userInfoBar'>
      <div className='logo'> Chatapp</div>
      <div className='userName'>{userName}</div>
      <button className='logout'>Logout</button>
    </div>
  )
}

export default UserInfobar
